const indexHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Smidja · Manager</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#10151d;color:#e7edf5}*{box-sizing:border-box}body{margin:0}header{padding:1rem 1.5rem;border-bottom:1px solid #334052;display:flex;align-items:center;gap:1rem;flex-wrap:wrap}h1{font-size:1.25rem;margin:0}h2{font-size:1.1rem}h3{font-size:1rem}small,.muted{color:#a8b8cc}button,input,textarea,select{font:inherit;border:1px solid #475b73;border-radius:.4rem;padding:.6rem;background:#1a2432;color:inherit}button{cursor:pointer}button:hover{background:#2b4058}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid #71d7bd;outline-offset:2px}button.primary{background:#175746}textarea{width:100%;resize:vertical;min-height:6rem}label{display:block;margin:.5rem 0}input{max-width:100%}nav{display:flex;gap:.4rem;flex-wrap:wrap;margin:1rem 0}nav button[aria-current="page"]{border-color:#71d7bd;color:#71d7bd}main{max-width:1400px;margin:auto;padding:1rem 1.5rem}.row{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}.grow{flex:1;min-width:8rem}.split{display:grid;grid-template-columns:260px minmax(0,1fr);gap:1rem}.card{background:#17202c;border:1px solid #334052;padding:1rem;border-radius:.6rem;margin-bottom:.75rem}.list{display:grid;gap:.4rem}.list button{text-align:left;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font: .9rem/1.5 ui-monospace,monospace;margin:.5rem 0;max-height:60vh;overflow:auto}.error{color:#ffb4ac}.notice{padding:.7rem;border:1px solid #475b73;border-radius:.4rem;margin:.5rem 0;white-space:pre-wrap}.board{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:.6rem}.board section{min-width:0}.board button{width:100%;text-align:left;margin:.2rem 0;overflow-wrap:anywhere}.message{border-left:3px solid #526d89;padding:.5rem 1rem;margin:.7rem 0}.message.user{border-color:#71d7bd}#editor{font: .9rem/1.5 ui-monospace,monospace;min-height:40vh}#login{max-width:450px;margin:8vh auto}#messages:empty:after{content:'Start a conversation with your CEO.';color:#a8b8cc}[hidden]{display:none!important}@media(max-width:700px){main{padding:1rem}.split{grid-template-columns:1fr}header{padding:1rem}.board{grid-template-columns:1fr 1fr}#sessions{max-height:180px;overflow:auto}button{min-height:42px}}
</style></head><body>
<header><h1>Smidja</h1><span class="muted">Your assistant, your machines.</span><span class="grow"></span><span id="connection" role="status">Not connected</span><button id="logout" hidden>Sign out</button></header>
<main><div id="notice" class="notice" role="alert" hidden></div>
<form id="login" class="card"><h2>Connect to your manager</h2><p class="muted">Use the access token configured on this manager. It is not saved in browser storage.</p><label for="token">Manager token</label><input id="token" type="password" required autocomplete="current-password" class="grow"><p><button class="primary">Connect</button></p></form>
<div id="app" hidden><nav aria-label="Main navigation"><button data-view="chat" aria-current="page">Conversations</button><button data-view="tasks">Taskboard</button><button data-view="files">Files &amp; diff</button><button data-view="devices">Devices</button><button data-view="teams">Teams</button><button data-view="configuration">Private configuration</button><button data-view="packages">Packages</button></nav>
<section id="chat" class="view"><div class="split"><aside class="card"><h2>Sessions</h2><form id="newSession"><label for="sessionTitle">New conversation</label><input id="sessionTitle" placeholder="Conversation title" required maxlength="200"><p><button>Create</button></p></form><div id="sessions" class="list"></div></aside><div class="card"><h2 id="chatTitle">Choose a conversation</h2><p id="turnState" role="status"></p><div id="messages"></div><form id="sendMessage"><label for="message">Message</label><textarea id="message" required></textarea><div class="row"><button id="send" class="primary" disabled>Send</button><button id="recover" type="button" disabled>Recover turn</button><button id="observe" type="button" disabled>Reconnect events</button><button id="cancelTurn" type="button" disabled>Cancel turn</button></div></form></div></div></section>
<section id="tasks" class="view" hidden><div class="row"><h2 class="grow">Taskboard</h2><button id="refreshTasks">Refresh</button></div><form id="prReview" class="card"><h3>Review a pull request</h3><p class="muted">Four read-only phases, pinned base/head commits. No code execution or GitHub publication.</p><label>Originating CEO conversation <select id="prSession" required></select></label><label>Repository (owner/name) <input id="prRepository" required pattern="[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"></label><label>PR number <input id="prNumber" type="number" min="1" required></label><label>Optional focus <textarea id="prFocus"></textarea></label><p><button class="primary">Start review in background</button></p><p id="prStatus" role="status"></p></form><div id="board" class="board"></div><div id="taskDetail" class="card" hidden><h2 id="taskTitle"></h2><p id="taskState"></p><div id="phaseOutputs"></div><label for="clarification">Resolution / clarification</label><textarea id="clarification"></textarea><div class="row"><button id="resumeTask">Resume blocked phase</button><button id="retryTask">Retry classification</button><button id="cancelTask">Cancel task</button></div></div></section>
<section id="files" class="view" hidden><h2>File explorer</h2><p class="muted">Files are accessed with the operating-system permissions of the selected machine. Text edits use a revision check; Git commands are read-only.</p><form id="browse" class="row"><label>Machine <select id="machine"><option value="manager">Manager</option></select></label><label class="grow">Directory <input id="path" value="/" class="grow" required></label><button>Open directory</button><button id="up" type="button">Up</button></form><p id="fileState" role="status"></p><div class="row"><button id="gitStatus">Git status</button><button id="gitDiff">Working-tree diff</button><button id="gitStaged">Staged diff</button></div><div class="split"><div id="entries" class="list card"></div><div class="card"><h3 id="fileTitle">Select a text file</h3><textarea id="editor" aria-label="File contents" spellcheck="false" disabled></textarea><p><button id="save" class="primary" disabled>Save file</button> <span id="saveState" role="status"></span></p><pre id="gitOutput" aria-label="Git output"></pre></div></div></section>
<section id="devices" class="view" hidden><div class="row"><h2 class="grow">Connected &amp; remembered devices</h2><button id="refreshDevices">Refresh</button></div><div id="deviceList"></div></section>
<section id="teams" class="view" hidden><h2>Teams</h2><p class="muted">Delegate through a conversation with an existing CEO turn. Native background execution returns a receipt immediately; results are delivered to the originating conversation.</p><button id="refreshTeams">Refresh teams</button><div id="teamList" class="list card"></div><form id="delegateTeam" class="card"><label>Originating conversation <select id="teamSession" required></select></label><label>Team <select id="teamRef" required></select></label><label for="teamPrompt">Request</label><textarea id="teamPrompt" required></textarea><p><button class="primary">Delegate in background</button></p><pre id="teamReceipt" role="status"></pre></form></section>
<section id="configuration" class="view" hidden><h2>Private configuration &amp; approvals</h2><p class="muted">Agent proposals remain inactive until you approve them. These records are separate from immutable package content. Catalog registration does not itself confirm remote team materialization or executable availability.</p><button id="refreshConfiguration">Refresh configuration</button><h3>Pending approvals</h3><div id="approvals"></div><div class="split"><div id="privateEntities" class="list card"></div><form id="privateEditor" class="card"><h3 id="privateTitle">Create a private record</h3><label>Type <select id="privateKind"><option value="team">Team</option><option value="workflow">Workflow</option><option value="extension">Extension</option></select></label><label for="privateID">Private ID</label><input id="privateID" value="private:" required pattern="private:[a-zA-Z0-9][a-zA-Z0-9._-]*"><label for="privatePayload">Definition (JSON)</label><textarea id="privatePayload" required spellcheck="false"></textarea><p id="privateRevision" class="muted">New record</p><div class="row"><button class="primary">Save owner change</button><button type="button" id="newPrivate">New record</button><button type="button" id="archivePrivate" disabled>Archive</button><button type="button" id="restorePrivate" disabled>Restore</button></div></form></div></section>
<section id="packages" class="view" hidden><h2>Installed packages</h2><p class="muted">Installed content is immutable. Installing a source trusts its publisher's future automatic updates; new publisher tools do not require individual approvals. Credentials stay in environment variables.</p><form id="installPackage" class="card"><label for="packageURL">Release manifest URL</label><input id="packageURL" type="url" required class="grow"><label for="packageTokenEnv">Authentication environment variable name (optional, not the token)</label><input id="packageTokenEnv" pattern="[A-Za-z_][A-Za-z0-9_]*"><p><button class="primary">Install package</button></p></form><button id="refreshPackages">Refresh packages</button><div id="packageList"></div><h3>Available package workflows</h3><div id="workflowList"></div></section>
</div></main>
<script>
'use strict';
const $=id=>document.getElementById(id);
const state={csrf:'',logged:false,view:'chat',session:null,workflowTaskID:null,chatID:null,turn:null,task:null,taskData:null,file:null,dirty:false,polling:false,sessionGeneration:0,fileGeneration:0,privateEntity:null,prSubmission:null};
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function notice(message,error=true){$('notice').textContent=message;$('notice').classList.toggle('error',error);$('notice').hidden=!message;}
function resetLogin(){state.logged=false;state.csrf='';state.session=null;state.workflowTaskID=null;state.turn=null;state.task=null;state.taskData=null;state.privateEntity=null;state.file=null;state.dirty=false;state.sessionGeneration++;state.fileGeneration++;$('app').hidden=true;$('logout').hidden=true;$('login').hidden=false;$('connection').textContent='Not connected';$('editor').value='';$('message').value='';$('messages').replaceChildren();for(const id of ['sessions','board','phaseOutputs','entries','deviceList','approvals','privateEntities','packageList','workflowList','teamList'])$(id).replaceChildren();$('gitOutput').textContent='';$('taskDetail').hidden=true;$('clarification').value='';$('privatePayload').value='';$('packageTokenEnv').value='';$('teamPrompt').value='';$('teamReceipt').textContent='';$('teamSession').replaceChildren();$('teamRef').replaceChildren();$('prSession').replaceChildren();$('prRepository').value='';$('prNumber').value='';$('prFocus').value='';$('prStatus').textContent='';state.prSubmission=null;}
async function api(path,body){const options={credentials:'same-origin',headers:{}};if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.headers['X-CSRF']=state.csrf;options.body=JSON.stringify(body);}const response=await fetch('/api/'+path,options);let data;try{data=await response.json();}catch(e){throw Error('Manager returned an unreadable response ('+response.status+').');}if(!response.ok){if(response.status===401)resetLogin();throw Error(data.error||'Request failed ('+response.status+').');}return data;}
function controls(){$('archivePrivate').disabled=!state.privateEntity||!!state.privateEntity.archived_at;$('restorePrivate').disabled=!state.privateEntity||!state.privateEntity.archived_at;$('observe').disabled=!state.session||!state.chatID;const turn=state.turn;const terminal=!turn||['completed','cancelled'].includes(turn.status);$('send').disabled=!state.session||!!state.workflowTaskID||!terminal;$('message').disabled=!!state.workflowTaskID;$('recover').disabled=!turn||turn.status!=='paused'||!turn.turn_id;$('cancelTurn').disabled=terminal;const task=state.taskData;if(task){const phase=task.phases[task.phase_index];const attempt=phase&&phase.attempts&&phase.attempts[phase.attempts.length-1];const classify=task.status==='paused'&&attempt&&attempt.output_recorded&&!attempt.decision;$('resumeTask').disabled=!['blocked','paused'].includes(task.status)||!!classify;$('retryTask').disabled=!classify;$('cancelTask').disabled=['completed','cancelled'].includes(task.status);}document.querySelectorAll('[data-busy]').forEach(b=>b.disabled=true);}
async function action(button,fn){if(button.disabled||button.dataset.busy)return;button.dataset.busy='true';button.disabled=true;notice('');try{await fn();}catch(e){notice(e.message);}finally{delete button.dataset.busy;button.disabled=false;controls();}}
function bind(id,fn){$(id).addEventListener('click',()=>action($(id),fn));}
function submit(id,fn){$(id).addEventListener('submit',e=>{e.preventDefault();action($(id).querySelector('button'),fn);});}
submit('login',async()=>{const data=await api('login',{token:$('token').value});state.csrf=data.csrf;state.logged=true;$('token').value='';$('login').hidden=true;$('app').hidden=false;$('logout').hidden=false;await refresh();});
bind('logout',async()=>{if(state.dirty&&!confirm('Discard unsaved file edits and sign out?'))return;await api('logout',{});resetLogin();});
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{state.view=button.dataset.view;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==state.view);document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b===button?'page':'false'));action(button,refresh);}));
async function sessions(){const list=await api('sessions');if(!state.logged)return;const box=$('sessions');box.replaceChildren();for(const session of list||[]){const b=node('button',session.title||session.id);b.type='button';b.onclick=()=>action(b,async()=>{if($('message').value&&!confirm('Discard this unsent message and change conversation?'))return;$('message').value='';state.session=session.id;state.turn=null;state.sessionGeneration++;await conversation();});box.append(b);}if(!list||!list.length)box.append(node('p','No conversations yet.','muted'));}
submit('newSession',async()=>{const session=await api('sessions',{title:$('sessionTitle').value});state.session=session.id;state.turn=null;state.sessionGeneration++;$('sessionTitle').value='';await sessions();await conversation();});
async function conversation(){const id=state.session,generation=state.sessionGeneration;if(!id)return;const session=await api('sessions/'+encodeURIComponent(id));if(id!==state.session||generation!==state.sessionGeneration||!state.logged)return;$('chatTitle').textContent=session.title||session.id;const turn=session.turn;state.turn=turn;state.chatID=session.chat_id;state.workflowTaskID=session.workflow_task_id;const running=turn&&turn.status==='running';$('turnState').textContent=state.workflowTaskID?'Workflow phase (read-only) · task '+state.workflowTaskID+' · use the originating CEO conversation':turn?turn.status+(turn.reason?' · '+turn.reason:''):'Ready';$('send').disabled=!!running;$('recover').disabled=!turn||running||!turn.turn_id;$('cancelTurn').disabled=!turn||['completed','cancelled'].includes(turn.status);const messages=$('messages');messages.replaceChildren();for(const message of session.messages||[]){const el=node('article',undefined,'message '+(message.role==='user'?'user':''));el.append(node('strong',message.role),node('pre',message.content));messages.append(el);}controls();}
submit('sendMessage',async()=>{if(!state.session)return;const id=state.session;await api('sessions/'+encodeURIComponent(id)+'/messages',{message:$('message').value});if(id===state.session)$('message').value='';await conversation();});
bind('observe',async()=>{await api('sessions/'+encodeURIComponent(state.session)+'/observe',{});notice('Event stream reconnection requested.',false);});
bind('recover',async()=>{await api('sessions/'+encodeURIComponent(state.session)+'/recover',{});await conversation();});
bind('cancelTurn',async()=>{await api('sessions/'+encodeURIComponent(state.session)+'/cancel',{});await conversation();});
async function tasks(){const generation=state.sessionGeneration;const [list,conversations,review]=await Promise.all([api('tasks'),api('sessions'),api('pr-review/status')]);if(!state.logged||generation!==state.sessionGeneration)return;const previous=$('prSession').value||state.session;$('prSession').replaceChildren();for(const session of conversations||[]){if(session.workflow_task_id||!session.chat_id||!session.turn||!session.turn.turn_id)continue;const option=node('option',session.title||session.id);option.value=session.id;$('prSession').append(option);}if([...$('prSession').options].some(o=>o.value===previous))$('prSession').value=previous;$('prStatus').textContent=!review.configured?'PR review is not configured on this manager.':review.poll&&review.poll.error?'Polling: '+review.poll.error:'Ready · read-only review';if(!state.logged)return;const board=$('board');board.replaceChildren();for(const status of ['queued','running','blocked','paused','completed','cancelled']){const column=node('section',undefined,'card');column.append(node('h3',status));for(const task of (list||[]).filter(t=>t.status===status)){const b=node('button',(task.workflow.id||task.id)+' · '+Math.min(task.phase_index+1,task.phases.length)+'/'+task.phases.length);b.onclick=()=>action(b,async()=>{state.task=task.id;await taskDetail();});column.append(b);}board.append(column);}if(state.task)await taskDetail();}
async function taskDetail(){const id=state.task;const task=await api('tasks/'+encodeURIComponent(id));if(id!==state.task||!state.logged)return;state.taskData=task;$('taskDetail').hidden=false;$('taskTitle').textContent=task.workflow.id+' · '+task.id;$('taskState').textContent=task.status+(task.reason?' · '+task.reason:'');const box=$('phaseOutputs');box.replaceChildren();box.append(node('pre',JSON.stringify(task.inputs,null,2)));if(task.focus)box.append(node('p',task.focus));for(const clarification of task.clarifications||[])box.append(node('p','Clarification: '+clarification));for(const phase of task.phases||[]){const details=node('details');details.open=phase.status==='blocked';details.append(node('summary',phase.phase.name+' · '+phase.status));for(const attempt of phase.attempts||[]){details.append(node('p','Attempt '+attempt.number+' · '+(attempt.decision||'Not classified')),node('pre',attempt.output||'(No output recorded)'));}box.append(details);}$('resumeTask').disabled=!['blocked','paused'].includes(task.status);$('retryTask').disabled=task.status!=='paused';$('cancelTask').disabled=['completed','cancelled'].includes(task.status);controls();}
bind('refreshTasks',tasks);
$('prReview').onsubmit=e=>{e.preventDefault();const button=e.submitter||$('prReview').querySelector('button');action(button,async()=>{const input={repository:$('prRepository').value,number:Number($('prNumber').value),focus:$('prFocus').value,origin_session_id:$('prSession').value};const serialized=JSON.stringify(input);if(!state.prSubmission||state.prSubmission.input!==serialized)state.prSubmission={input:serialized,id:'ui-'+Date.now()+'-'+Math.random().toString(36).slice(2)};input.request_id=state.prSubmission.id;const task=await api('pr-review',input);if(!state.logged)return;state.prSubmission=null;state.task=task.id;await tasks();});};
bind('resumeTask',async()=>{await api('tasks/'+encodeURIComponent(state.task)+'/resume',{clarification:$('clarification').value});$('clarification').value='';await tasks();});
bind('retryTask',async()=>{await api('tasks/'+encodeURIComponent(state.task)+'/retry-classification',{});await tasks();});
bind('cancelTask',async()=>{if(!confirm('Cancel this workflow task?'))return;await api('tasks/'+encodeURIComponent(state.task)+'/cancel',{});await tasks();});
async function devices(){const list=await api('devices');if(!state.logged)return;const box=$('deviceList');box.replaceChildren();const selected=$('machine').value;const select=$('machine');select.replaceChildren();const manager=node('option','Manager');manager.value='manager';select.append(manager);for(const device of list||[]){const inventory=device.inventory||{};const card=node('article',undefined,'card');card.append(node('h3',device.name+' · '+(device.online?'Online':'Offline')),node('p',device.id+' · '+(inventory.os||'?')+'/'+(inventory.arch||'?')),node('p','Last seen: '+(device.last_seen||'Never')),node('pre','Tools: '+(inventory.tools||[]).join(', ')+'\nTeams: '+(inventory.teams||[]).join(', ')));box.append(card);const option=node('option',device.name+(device.online?'':' (offline)'));option.value=device.id;select.append(option);}if([...select.options].some(o=>o.value===selected))select.value=selected;else if(selected!=='manager'){const option=node('option',selected+' (unavailable)');option.value=selected;select.append(option);select.value=selected;}if(!list||!list.length)box.append(node('p','No registered clients. Manager tools remain available.','muted'));}
bind('refreshDevices',devices);
async function tool(name,args,client){const result=await api('tools/execute',{client_id:client===undefined?$('machine').value:client,name,args});if(!result.ok)throw Error((result.code?result.code+': ':'')+(result.error||'Tool failed.'));$('fileState').textContent=result.truncated?'Result truncated by machine limits.':'';return result.data;}
function mayDiscard(){return !state.dirty||confirm('Discard unsaved file edits?');}
function clearFile(){state.file=null;state.dirty=false;$('editor').value='';$('editor').disabled=true;$('save').disabled=true;$('fileTitle').textContent='Select a text file';$('saveState').textContent='';}
async function browse(path){if(!mayDiscard())return;const client=$('machine').value,generation=++state.fileGeneration;const data=await tool('list',{path},client);if(generation!==state.fileGeneration||client!==$('machine').value||!state.logged)return;clearFile();$('path').value=data.path;$('gitOutput').textContent='';const entries=$('entries');entries.replaceChildren();for(const entry of data.entries||[]){const b=node('button',(entry.directory?'▸ ':'')+entry.name+(entry.symlink?' ↗':''));b.onclick=()=>action(b,()=>entry.directory?browse(entry.path):openFile(entry.path));entries.append(b);}if(!data.entries||!data.entries.length)entries.append(node('p','Empty directory.','muted'));}
async function openFile(path){if(!mayDiscard())return;const client=$('machine').value,generation=++state.fileGeneration;const data=await tool('read',{path},client);if(generation!==state.fileGeneration||client!==$('machine').value||!state.logged)return;state.file={path:data.path,sha256:data.sha256,client};state.dirty=false;$('fileTitle').textContent=data.path;$('editor').value=data.content;$('editor').disabled=false;$('save').disabled=false;$('saveState').textContent='';}
submit('browse',()=>browse($('path').value));
bind('up',()=>browse($('path').value.replace(/\/+$/,'').replace(/\/[^/]*$/,'')||'/'));
$('machine').addEventListener('change',()=>{state.fileGeneration++;$('entries').replaceChildren();$('gitOutput').textContent='';$('fileState').textContent='Select Open directory to browse this machine.';if(state.file)$('saveState').textContent='Editor remains bound to '+state.file.client+' until another file is opened.';});
$('editor').addEventListener('input',()=>{state.dirty=true;$('saveState').textContent='Unsaved changes';});
bind('save',async()=>{if(!state.file)return;const file=state.file,content=$('editor').value;const data=await tool('write',{path:file.path,content,expected_sha256:file.sha256},file.client);if(state.file!==file)return;state.file.sha256=data.sha256;state.dirty=$('editor').value!==content;$('saveState').textContent=state.dirty?'Saved previous revision; newer edits are unsaved.':'Saved';});
async function git(name,staged){const client=$('machine').value,generation=state.fileGeneration;const data=await tool(name,{path:$('path').value,staged},client);if(generation!==state.fileGeneration||client!==$('machine').value)return;$('gitOutput').textContent=data.root+'\n'+(data.output.replace(/\u0000/g,'\n')||'No changes.');}
bind('gitStatus',()=>git('git_status',false));bind('gitDiff',()=>git('git_diff',false));bind('gitStaged',()=>git('git_diff',true));
async function refresh(){if(!state.logged)return;const status=await api('status');$('connection').textContent=status.configured?'Manager connected · Envai configured':'Manager connected · Envai not configured';if(state.view==='chat'){await sessions();await conversation();}else if(state.view==='tasks')await tasks();else if(state.view==='teams')await teams();else if(state.view==='configuration')await configuration();else if(state.view==='packages')await packages();else await devices();}


async function teams(){const [catalog,conversations]=await Promise.all([api('teams'),api('sessions')]);if(!state.logged)return;const list=$('teamList');list.replaceChildren();const previous=$('teamRef').value;$('teamRef').replaceChildren();for(const team of catalog||[]){list.append(node('p',team.name+' · '+team.id+' · '+team.origin));const option=node('option',team.name+' ('+team.id+')');option.value=team.id;$('teamRef').append(option);}if([...$('teamRef').options].some(o=>o.value===previous))$('teamRef').value=previous;const origin=$('teamSession').value||state.session;$('teamSession').replaceChildren();for(const session of conversations||[]){if(session.workflow_task_id||!session.chat_id||!session.turn||!session.turn.turn_id)continue;const option=node('option',session.title||session.id);option.value=session.id;$('teamSession').append(option);}if([...$('teamSession').options].some(o=>o.value===origin))$('teamSession').value=origin;if(!catalog||!catalog.length)list.append(node('p','No teams available.','muted'));if(!$('teamSession').options.length)list.append(node('p','Send a message in a CEO conversation first to establish its native origin.','muted'));}
bind('refreshTeams',teams);
submit('delegateTeam',async()=>{if(!$('teamSession').value||!$('teamRef').value)throw Error('Select an originating conversation and a team.');const result=await api('team-delegations',{session_id:$('teamSession').value,team_ref:$('teamRef').value,prompt:$('teamPrompt').value});if(!result.ok)throw Error(result.error||'Delegation failed.');$('teamReceipt').textContent='Native delegation accepted. This is a receipt, not a completed result.\n'+JSON.stringify(result.data,null,2);$('teamPrompt').value='';});

const privateExamples={team:{name:'New team',agents:[{name:'Manager',instructions:'',model:'',tools:[]}]},workflow:{id:'workflow',version:'1',phases:[{id:'phase-1',name:'First phase',team_ref:'private:team'}]},extension:{name:'New extension',description:'',parameters:{type:'object',properties:{}},command:['python3','tool.py'],environment:{},client_id:'manager'}};
function newPrivate(){state.privateEntity=null;$('privateID').disabled=false;$('privateKind').disabled=false;$('privateID').value='private:';$('privateTitle').textContent='Create a private record';$('privateRevision').textContent='New record';$('privatePayload').value=JSON.stringify(privateExamples[$('privateKind').value],null,2);$('archivePrivate').disabled=true;$('restorePrivate').disabled=true;}
$('privateKind').addEventListener('change',newPrivate);
bind('newPrivate',newPrivate);
async function configuration(){const [entities,approvals,activations]=await Promise.all([api('private?archived=true'),api('approvals'),api('private/activation')]);if(!state.logged)return;const list=$('privateEntities');list.replaceChildren();for(const entity of entities||[]){const activation=(activations||[]).find(a=>a.id===entity.id);const b=node('button',entity.id+' · '+entity.kind+(entity.archived_at?' · archived':'')+(activation?' · '+activation.client_id+' · '+activation.status:''));b.onclick=()=>{state.privateEntity=entity;$('privateID').value=entity.id;$('privateID').disabled=true;$('privateKind').value=entity.kind;$('privateKind').disabled=true;$('privatePayload').value=JSON.stringify(entity.payload,null,2);$('privateTitle').textContent=entity.id;$('privateRevision').textContent='Revision '+entity.revision+(entity.expires_at?' · Archived until '+entity.expires_at:'');$('archivePrivate').disabled=!!entity.archived_at;$('restorePrivate').disabled=!entity.archived_at;};list.append(b);}if(!entities||!entities.length)list.append(node('p','No private records.','muted'));const box=$('approvals');box.replaceChildren();for(const proposal of approvals||[]){const card=node('article',undefined,'card');const change=proposal.change;card.append(node('h3',change.action+' '+change.kind+' · '+change.id),node('p','Proposal '+proposal.id+' · expected revision '+change.base_revision));const current=(entities||[]).find(e=>e.id===change.id);card.append(node('h4','Current record'),node('pre',JSON.stringify(current||null,null,2)),node('h4','Exact proposed change'),node('pre',JSON.stringify(change,null,2)));if(current&&current.revision!==change.base_revision)card.append(node('p','Stale proposal: current revision differs. Approval will be rejected.','error'));const approve=node('button','Approve exact change');approve.onclick=()=>action(approve,async()=>{if(!confirm('Approve this exact '+change.action+' proposal for '+change.id+'?'))return;await api('approvals/'+encodeURIComponent(proposal.id)+'/approve',{});await configuration();});const reject=node('button','Reject');reject.onclick=()=>action(reject,async()=>{await api('approvals/'+encodeURIComponent(proposal.id)+'/reject',{});await configuration();});card.append(approve,reject);box.append(card);}if(!approvals||!approvals.length)box.append(node('p','No pending approvals.','muted'));if(!$('privatePayload').value)newPrivate();}
bind('refreshConfiguration',configuration);
submit('privateEditor',async()=>{const old=state.privateEntity;if(old&&old.archived_at)throw Error('Restore the archived record before editing.');const change={action:old?'update':'create',id:$('privateID').value,kind:$('privateKind').value,base_revision:old?old.revision:0,payload:JSON.parse($('privatePayload').value)};const entity=await api('private',change);state.privateEntity=entity;$('privateID').disabled=true;$('privateKind').disabled=true;$('privateRevision').textContent='Revision '+entity.revision;$('archivePrivate').disabled=false;notice('Owner change saved to the private catalog.',false);await configuration();});
async function privateLifecycle(action){const entity=state.privateEntity;if(!entity)return;if(action==='archive'&&!confirm('Archive '+entity.id+'? It can be restored for 30 days.'))return;const updated=await api('private',{action,id:entity.id,kind:entity.kind,base_revision:entity.revision});state.privateEntity=updated;$('privateRevision').textContent='Revision '+updated.revision+(updated.expires_at?' · Archived until '+updated.expires_at:'');$('archivePrivate').disabled=!!updated.archived_at;$('restorePrivate').disabled=!updated.archived_at;await configuration();}
bind('archivePrivate',()=>privateLifecycle('archive'));bind('restorePrivate',()=>privateLifecycle('restore'));
async function packages(){const [revisions,status,workflows]=await Promise.all([api('packages'),api('packages/update-status'),api('workflows')]);if(!state.logged)return;const list=$('packageList');list.replaceChildren();for(const revision of revisions||[]){const card=node('article',undefined,'card');card.append(node('h3',revision.id+' · '+revision.version),node('pre','Digest: '+revision.digest),node('p','Source: '+revision.source.url));if(status&&status[revision.id])card.append(node('pre','Update error: '+status[revision.id],'error'));const update=node('button','Check for update');update.onclick=()=>action(update,async()=>{await api('packages/update',{id:revision.id});await packages();});const manifest=node('details');manifest.append(node('summary','Installed manifest'),node('pre',JSON.stringify(revision.manifest,null,2)));card.append(update,manifest);list.append(card);}if(!revisions||!revisions.length)list.append(node('p','No installed packages.','muted'));const workflowsBox=$('workflowList');workflowsBox.replaceChildren();for(const workflow of workflows||[]){const details=node('details',undefined,'card');details.append(node('summary',workflow.id+' · '+workflow.version),node('pre',JSON.stringify(workflow,null,2)));workflowsBox.append(details);}if(!workflows||!workflows.length)workflowsBox.append(node('p','No available workflows.','muted'));}
bind('refreshPackages',packages);
submit('installPackage',async()=>{await api('packages/install',{url:$('packageURL').value,token_env:$('packageTokenEnv').value});$('packageURL').value='';$('packageTokenEnv').value='';await packages();notice('Package installed. Automatic publisher updates are enabled.',false);});

setInterval(async()=>{if(!state.logged||state.polling||document.hidden)return;state.polling=true;try{if(state.view==='chat')await conversation();else if(state.view==='tasks')await tasks();else if(state.view==='devices')await devices();}catch(e){notice('Refresh failed: '+e.message);}finally{state.polling=false;}},4000);
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});
</script></body></html>`
